def valid_date(date):
    # Check whether the date matches the required format 'mm-dd-yyyy'
    pattern = re.compile(r"^(?:(?:0[1-9]|1\d|2[0-8])-(?:0[1-9]|1[012])|(?:29|30)-(?:0[13-9]|1[012])|31-(?:0[13-9]|1[02]))-\d{4}$")

    if not pattern.match(date):
        return False

    # Try converting the date to datetime object and catch exceptions if any
    try:
        datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    return True

