def fix_spaces(text):
    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 2:
                result.append('-')
            elif space_count > 0:
                result.extend(['_'] * space_count)
            space_count = 0
            result.append(char)

    # Handle trailing spaces
    if space_count > 2:
        result.append('-')
    elif space_count > 0:
        result.extend(['_'] * space_count)

    return ''.join(result)
def fix_spaces(text):
    result = ""
    i = 0
    while i < len(text):
        if text[i] == ' ':
            j = i
            while j < len(text) and text[j] == ' ':
                j += 1
            if j - i > 2:
                result += '-'
            else:
                for k in range(j - i):
                    result += '_'
            i = j
        else:
            result += text[i]
            i += 1
    return result

