def largest_prime_factor(n: int) -> int:
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    # Initialize the smallest prime factor
    factor = 2

    # Divide n by the smallest factors until n becomes 1
    while factor * factor <= n:
        if n % factor == 0:
            n //= factor
        else:
            factor += 1

    # When n is reduced to a number greater than 1, it must be prime
    return n

